//! 🧺️ A resident native array allocation retains its initialized prefix and original Work.
use semio_framework_value_control_contract::{OriginalEffectReply,OriginalEffectReplyComplete,OriginalWorkBindingIdentity,RetainedAllocationEffect,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,ValueRefusalKind,retained_clone_grant_admits};
use std::{alloc::{alloc,dealloc,Layout},mem::{size_of,MaybeUninit},ptr::NonNull};
fn invalid(message:&'static str)->ValueError{ValueError::invariant(message)}
fn extent(parts:&[usize])->Result<usize,ValueError>{parts.iter().try_fold(0usize,|sum,n|sum.checked_add(*n).ok_or_else(||invalid("array backing extent overflow")))}
/// 📦️ The original native allocation remains resident until its initialized prefix is transferred or retired.
pub struct NativeArrayBacking<T,const N:usize>{pointer:Option<NonNull<MaybeUninit<T>>>,initialized:usize,work:Option<OriginalWorkBindingIdentity>}
unsafe impl<T:Send,const N:usize> Send for NativeArrayBacking<T,N>{}
impl<T,const N:usize> NativeArrayBacking<T,N>{
 /// 🌱️ Creates only an empty native seed without allocation or callback.
 pub const fn new()->Self{Self{pointer:None,initialized:0,work:None}}
 fn layout()->Result<Layout,ValueError>{Layout::array::<T>(N).map_err(|_|invalid("array backing layout overflow"))}
 fn authenticate(&self,effect:&RetainedAllocationEffect<'_>)->Result<(),ValueError>{if !self.work.is_some_and(|work|work.matches_effect(effect)){return Err(invalid("array backing changed original Work"))}Ok(())}
 fn preflight(effect:&RetainedAllocationEffect<'_>,d:RetirementDemand)->Result<bool,ValueError>{Ok(effect.remaining_work_units()?>=1&&retained_clone_grant_admits(effect.grant(),d))}
 fn performed(effect:&mut RetainedAllocationEffect<'_>)->Result<(),ValueError>{if effect.performed(1)?{Ok(())}else{Err(ValueError::literal(ValueRefusalKind::WorkLimit,"array backing exceeded original Work"))}}
 /// 📏️ Quotes the actual allocation and only its resident native headers.
 pub fn reserve_demand()->Result<RetirementDemand,ValueError>{let layout=Self::layout()?;let markers=if layout.size()==0{0}else{2*size_of::<Option<usize>>()};Ok(RetirementDemand{copy_bytes:extent(&[size_of::<Option<NonNull<MaybeUninit<T>>>>(),size_of::<Option<OriginalWorkBindingIdentity>>(),markers])?,capacity_bytes:layout.size(),depth:1,..Default::default()})}
 /// 🏗️ Publishes the exact native allocation in the owner before replying.
 pub fn reserve_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{if self.pointer.is_some()||self.work.is_some()||self.initialized!=0{return Err(invalid("array backing is already reserved"))}if effect.work_source_turn().is_none(){return Err(invalid("array backing requires original Source"))}let d=Self::reserve_demand()?;if !Self::preflight(effect,d)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if effect.actual().is_some(){return Err(invalid("array backing allocation marker occupied"))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}let layout=Self::layout()?;let pointer=if layout.size()==0{NonNull::<MaybeUninit<T>>::dangling()}else{*effect.actual()=Some(0);let raw=unsafe{alloc(layout)}.cast::<MaybeUninit<T>>();let Some(pointer)=NonNull::new(raw)else{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"array backing allocation refused"))))};*effect.actual()=Some(layout.size());pointer};self.pointer=Some(pointer);self.work=Some(OriginalWorkBindingIdentity::from_effect(effect));Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))))}
 /// 🔎️ Reports whether the original native allocation is resident.
 pub fn reserved(&self)->bool{self.pointer.is_some()}
 /// 🔢️ Reports the exact resident initialized prefix.
 pub fn initialized(&self)->usize{self.initialized}
 /// 🪪️ Borrows the allocation address without changing its ownership.
 pub fn as_ptr(&self)->Option<*const T>{self.pointer.map(|pointer|pointer.as_ptr().cast::<T>() as *const T)}
 /// 👁️ Borrows only the actually initialized prefix.
 pub fn as_slice(&self)->Option<&[T]>{self.pointer.map(|pointer|unsafe{std::slice::from_raw_parts(pointer.as_ptr().cast::<T>(),self.initialized)})}
 /// 📏️ Quotes moving one actual typed element and its initialized count.
 pub fn element_demand()->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:extent(&[size_of::<T>(),size_of::<Option<T>>(),size_of::<usize>()])?,depth:1,..Default::default()})}
 /// 📥️ Moves one caller-resident element directly into the next original array slot.
 pub fn push_from<'r>(&mut self,input:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let pointer=self.pointer.ok_or_else(||invalid("array backing is absent"))?;if self.initialized==N||input.is_none(){return Err(invalid("array backing requires one next input"))}let d=Self::element_demand()?;if !Self::preflight(effect,d)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}let value=input.take().ok_or_else(||invalid("array backing input disappeared"))?;unsafe{pointer.as_ptr().add(self.initialized).write(MaybeUninit::new(value))};self.initialized+=1;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 /// 📤️ Returns the final initialized element into the caller's resident slot.
 pub fn pop_into<'r>(&mut self,output:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let pointer=self.pointer.ok_or_else(||invalid("array backing is absent"))?;if output.is_some(){return Err(invalid("array backing output occupied"))}if self.initialized==0{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let d=Self::element_demand()?;if !Self::preflight(effect,d)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}let index=self.initialized-1;*output=Some(unsafe{pointer.as_ptr().add(index).read().assume_init()});self.initialized=index;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 /// 📏️ Quotes only the actual pointer, output and authority headers.
 pub fn publication_header_demand()->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:extent(&[size_of::<Option<NonNull<MaybeUninit<T>>>>(),size_of::<Option<Box<[T;N]>>>(),size_of::<usize>(),size_of::<Option<OriginalWorkBindingIdentity>>()])?,depth:1,..Default::default()})}
 /// 📏️ Quotes publication only when the actual initialized prefix is complete.
 pub fn publication_demand(&self)->Result<RetirementDemand,ValueError>{if self.pointer.is_none()||self.initialized!=N{return Err(invalid("array backing is not fully initialized"))}Self::publication_header_demand()}
 /// 🫴️ Publishes the exact original allocation as a boxed initialized array.
 pub fn publish_into<'r>(&mut self,output:&mut Option<Box<[T;N]>>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;if output.is_some(){return Err(invalid("array output occupied"))}let d=self.publication_demand()?;if !Self::preflight(effect,d)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}let pointer=self.pointer.take().ok_or_else(||invalid("array backing disappeared"))?;*output=Some(unsafe{Box::from_raw(pointer.as_ptr().cast::<[T;N]>())});self.initialized=0;self.work=None;Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 /// 📏️ Quotes returning an empty original allocation.
 pub fn release_header_demand()->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:extent(&[size_of::<Option<NonNull<MaybeUninit<T>>>>(),size_of::<Option<OriginalWorkBindingIdentity>>()])?,release_bytes:Self::layout()?.size(),depth:1,..Default::default()})}
 /// 📏️ Quotes release only when the actual prefix is empty.
 pub fn release_demand(&self)->Result<RetirementDemand,ValueError>{if self.pointer.is_none()||self.initialized!=0{return Err(invalid("array backing is not empty"))}Self::release_header_demand()}
 /// ♻️ Releases only the original empty native allocation.
 pub fn release_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let d=self.release_demand()?;if !Self::preflight(effect,d)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}let pointer=self.pointer.take().ok_or_else(||invalid("array backing disappeared"))?;let layout=Self::layout()?;if layout.size()!=0{unsafe{dealloc(pointer.as_ptr().cast::<u8>(),layout)}}self.work=None;Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))))}
 /// ✅️ Reports that no original allocation or Work binding remains.
 pub fn terminal_is_empty(&self)->bool{self.pointer.is_none()&&self.initialized==0&&self.work.is_none()}
}
impl<T,const N:usize> NativeArrayBacking<T,N>{
 /// 📏️ Quotes a bounded native prefix copy and its initialized header.
 pub fn copy_demand(count:usize)->Result<RetirementDemand,ValueError>{if count==0{return Ok(Default::default())}let bytes=size_of::<T>().checked_mul(count).ok_or_else(||invalid("array copy extent overflow"))?;Ok(RetirementDemand{copy_bytes:extent(&[bytes,size_of::<usize>()])?,depth:1,..Default::default()})}
 /// ⛽️ Quotes the actual bounded native item and header work.
 pub fn copy_work(count:usize)->Result<u64,ValueError>{if count==0{return Ok(0)}let per=u64::try_from(size_of::<T>()).ok().and_then(|width|width.checked_add(2)).ok_or_else(||invalid("array copy Work overflow"))?;u64::try_from(count).ok().and_then(|n|n.checked_mul(per)).and_then(|n|n.checked_add(1)).ok_or_else(||invalid("array copy Work overflow"))}
 /// 📥️ Copies one admitted prefix from the caller's authentic immutable source.
 /// # Safety
 /// T must be Copy and the source must not overlap the resident destination.
 pub unsafe fn copy_from_slice_unchecked<'r>(&mut self,source:&[T],count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let pointer=self.pointer.ok_or_else(||invalid("array backing is absent"))?;let end=self.initialized.checked_add(count).filter(|end|*end<=N).ok_or_else(||invalid("array copy exceeds backing"))?;if count>source.len(){return Err(invalid("array copy exceeds original source"))}if count==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let d=Self::copy_demand(count)?;let work=Self::copy_work(count)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"array copy exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}unsafe{std::ptr::copy_nonoverlapping(source.as_ptr(),pointer.as_ptr().cast::<T>().add(self.initialized),count)}self.initialized=end;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
}
impl<T,const N:usize> NativeArrayBacking<T,N>{
 /// 📏️ Quotes a bounded native Copy-prefix discard.
 pub fn discard_demand(count:usize)->Result<RetirementDemand,ValueError>{if count==0{return Ok(Default::default())}Ok(RetirementDemand{copy_bytes:size_of::<usize>(),depth:1,..Default::default()})}
 /// ⛽️ Quotes each discarded native Copy item and the actual header update.
 pub fn discard_work(count:usize)->Result<u64,ValueError>{if count==0{return Ok(0)}u64::try_from(count).ok().and_then(|n|n.checked_add(1)).ok_or_else(||invalid("array discard Work overflow"))}
 /// ♻️ Retires a bounded suffix of actual native Copy elements.
 /// # Safety
 /// T must be Copy, so the selected initialized elements have no destructor.
 pub unsafe fn discard_copy_unchecked<'r>(&mut self,count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;if self.pointer.is_none()||count>self.initialized{return Err(invalid("array discard exceeds initialized prefix"))}if count==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let d=Self::discard_demand(count)?;let work=Self::discard_work(count)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"array discard exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}self.initialized-=count;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
}
impl<T:Copy,const N:usize> NativeArrayBacking<T,N>{
 /// 🪡️ Copies a native Copy prefix without invoking any user callback.
 pub fn copy_from_slice<'r>(&mut self,source:&[T],count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{unsafe{self.copy_from_slice_unchecked(source,count,effect,reply)}}
 /// ♻️ Discards native Copy elements under the original Work.
 pub fn discard_copy<'r>(&mut self,count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{unsafe{self.discard_copy_unchecked(count,effect,reply)}}
}
impl<T,const N:usize> NativeArrayBacking<Option<T>,N>{
 /// 📏️ Quotes the actual empty typed slots and initialized-prefix header.
 pub fn fill_none_demand(count:usize)->Result<RetirementDemand,ValueError>{Self::copy_demand(count)}
 /// ⛽️ Quotes the bounded native empty-slot initialization.
 pub fn fill_none_work(count:usize)->Result<u64,ValueError>{Self::copy_work(count)}
 /// 🌱️ Initializes only the next admitted slots without constructing or dropping a payload.
 pub fn fill_none_into<'r>(&mut self,count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let pointer=self.pointer.ok_or_else(||invalid("array backing is absent"))?;let end=self.initialized.checked_add(count).filter(|end|*end<=N).ok_or_else(||invalid("empty slot initialization exceeds backing"))?;if count==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let d=Self::fill_none_demand(count)?;let work=Self::fill_none_work(count)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"empty slot initialization exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}for index in self.initialized..end{unsafe{pointer.as_ptr().cast::<Option<T>>().add(index).write(None)}}self.initialized=end;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 /// 📏️ Quotes only the actual initialized-prefix header write.
 pub fn discard_none_demand(count:usize)->Result<RetirementDemand,ValueError>{if count==0{return Ok(Default::default())}Ok(RetirementDemand{copy_bytes:size_of::<usize>(),depth:1,..Default::default()})}
 /// ⛽️ Quotes every selected slot inspection and the terminal header write.
 pub fn discard_none_work(count:usize)->Result<u64,ValueError>{Self::copy_work(count)}
 /// ♻️ Discards a verified empty suffix while retaining any actual payload on refusal.
 pub fn discard_none_into<'r>(&mut self,count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let pointer=self.pointer.ok_or_else(||invalid("array backing is absent"))?;let start=self.initialized.checked_sub(count).ok_or_else(||invalid("empty slot discard exceeds initialized prefix"))?;if count==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let d=Self::discard_none_demand(count)?;let work=Self::discard_none_work(count)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work-1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"empty slot inspection exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}let mut occupied=false;for index in start..self.initialized{occupied|=unsafe{(&*pointer.as_ptr().cast::<Option<T>>().add(index)).is_some()}}if occupied{return Ok(reply.complete(Err(invalid("empty slot discard encountered an original payload"))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"empty slot discard exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}self.initialized=start;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
}
impl<const N:usize> NativeArrayBacking<u16,N>{
 /// 📏️ Quotes the actual native FIFO indices and initialized-prefix header.
 pub fn fill_indices_demand(count:usize)->Result<RetirementDemand,ValueError>{Self::copy_demand(count)}
 /// ⛽️ Quotes the bounded native FIFO-index initialization.
 pub fn fill_indices_work(count:usize)->Result<u64,ValueError>{Self::copy_work(count)}
 /// 🔢️ Initializes the next original FIFO indices without a callback or temporary collection.
 pub fn fill_indices_into<'r>(&mut self,count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let pointer=self.pointer.ok_or_else(||invalid("array backing is absent"))?;let end=self.initialized.checked_add(count).filter(|end|*end<=N).ok_or_else(||invalid("FIFO initialization exceeds backing"))?;if count==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}u16::try_from(end-1).map_err(|_|invalid("FIFO index exceeds native width"))?;let d=Self::fill_indices_demand(count)?;let work=Self::fill_indices_work(count)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"FIFO initialization exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}for index in self.initialized..end{unsafe{pointer.as_ptr().cast::<u16>().add(index).write(index as u16)}}self.initialized=end;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
}
impl<T,const N:usize> Default for NativeArrayBacking<T,N>{fn default()->Self{Self::new()}}
impl<T,const N:usize> Drop for NativeArrayBacking<T,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native array backing retains its original allocation")}}
